    DnssecKey.add_member(:digest_type, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableInteger, location_name: 'DigestType', traits: {"smithy.api#documentation" => "<p> The number of the DS digest algorithm according to an IANA assignment.</p>\n         <p>For more information, see <a href=\"https://www.iana.org/assignments/ds-rr-types/ds-rr-types.xhtml\">IANA</a>\n\t\t\tfor DNSSEC Delegation Signer (DS) Resource Record (RR) Type Digest Algorithms. </p>"}))
    DnssecKey.add_member(:digest, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Digest', traits: {"smithy.api#documentation" => "<p> The delegation signer digest.</p>\n         <p>Digest is calculated from the public key provided using specified digest algorithm and\n\t\t\tthis digest is the actual value returned from the registry nameservers as the value of\n\t\t\tDS records. </p>"}))
    DnssecKey.add_member(:key_tag, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableInteger, location_name: 'KeyTag', traits: {"smithy.api#documentation" => "<p> A numeric identification of the DNSKEY record referred to by this DS record. </p>"}))
    DnssecKey.add_member(:id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Id', traits: {"smithy.api#documentation" => "<p> An ID assigned to each DS record created by <a href=\"https://docs.aws.amazon.com/Route53/latest/APIReference/API_domains_AssociateDelegationSignerToDomain.html\">AssociateDelegationSignerToDomain</a>. </p>"}))
