    GetDomainSuggestionsRequest.add_member(:only_available, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'OnlyAvailable', traits: {"smithy.api#documentation" => "<p>If <code>OnlyAvailable</code> is <code>true</code>, Route 53 returns only domain names\n\t\t\tthat are available. If <code>OnlyAvailable</code> is <code>false</code>, Route 53\n\t\t\treturns domain names without checking whether they're available to be registered. To\n\t\t\tdetermine whether the domain is available, you can call\n\t\t\t\t<code>checkDomainAvailability</code> for each suggestion.</p>", "smithy.api#required" => {}}))
