    RegisterDomainRequest.add_member(:domain_name, Smithy::Schema::Shapes::ShapeRef.new(shape: DomainName, location_name: 'DomainName', traits: {"smithy.api#documentation" => "<p>The domain name that you want to register. The top-level domain (TLD), such as .com,\n\t\t\tmust be a TLD that Route 53 supports. For a list of supported TLDs, see <a href=\"https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/registrar-tld-list.html\">Domains that You Can Register with Amazon Route 53</a> in the <i>Amazon\n\t\t\t\tRoute 53 Developer Guide</i>.</p>\n         <p>The domain name can contain only the following characters:</p>\n         <ul>\n            <li>\n               <p>Letters a through z. Domain names are not case sensitive.</p>\n            </li>\n            <li>\n               <p>Numbers 0 through 9.</p>\n            </li>\n            <li>\n               <p>Hyphen (-). You can't specify a hyphen at the beginning or end of a label.\n\t\t\t\t</p>\n            </li>\n            <li>\n               <p>Period (.) to separate the labels in the name, such as the <code>.</code> in\n\t\t\t\t\t\t<code>example.com</code>.</p>\n            </li>\n         </ul>\n         <p>Internationalized domain names are not supported for some top-level domains. To\n\t\t\tdetermine whether the TLD that you want to use supports internationalized domain names,\n\t\t\tsee <a href=\"https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/registrar-tld-list.html\">Domains that You Can\n\t\t\t\tRegister with Amazon Route 53</a>. For more information, see <a href=\"https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/DomainNameFormat.html#domain-name-format-idns\">Formatting Internationalized Domain Names</a>. </p>", "smithy.api#required" => {}}))
    RegisterDomainRequest.add_member(:idn_lang_code, Smithy::Schema::Shapes::ShapeRef.new(shape: LangCode, location_name: 'IdnLangCode', traits: {"smithy.api#documentation" => "<p>Reserved for future use.</p>"}))
    RegisterDomainRequest.add_member(:duration_in_years, Smithy::Schema::Shapes::ShapeRef.new(shape: DurationInYears, location_name: 'DurationInYears', traits: {"smithy.api#documentation" => "<p>The number of years that you want to register the domain for. Domains are registered\n\t\t\tfor a minimum of one year. The maximum period depends on the top-level domain. For the\n\t\t\trange of valid values for your domain, see <a href=\"https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/registrar-tld-list.html\">Domains that You Can\n\t\t\t\tRegister with Amazon Route 53</a> in the <i>Amazon Route 53 Developer\n\t\t\t\tGuide</i>.</p>\n         <p>Default: 1</p>", "smithy.api#required" => {}}))
    RegisterDomainRequest.add_member(:auto_renew, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AutoRenew', traits: {"smithy.api#documentation" => "<p>Indicates whether the domain will be automatically renewed (<code>true</code>) or not\n\t\t\t\t(<code>false</code>). Auto renewal only takes effect after the account is\n\t\t\tcharged.</p>\n         <p>Default: <code>true</code>\n         </p>"}))
