    RegisterDomainRequest.add_member(:privacy_protect_admin_contact, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'PrivacyProtectAdminContact', traits: {"smithy.api#documentation" => "<p>Whether you want to conceal contact information from WHOIS queries. If you specify\n\t\t\t\t<code>true</code>, WHOIS (\"who is\") queries return contact information either for\n\t\t\tAmazon Registrar or for our registrar associate,\n\t\t\tGandi. If you specify <code>false</code>, WHOIS queries return the\n\t\t\tinformation that you entered for the admin contact.</p>\n         <note>\n            <p>You must specify the same privacy setting for the administrative, billing, registrant, and\n\t\t\t\ttechnical contacts.</p>\n         </note>\n         <p>Default: <code>true</code>\n         </p>"}))
    RegisterDomainRequest.add_member(:privacy_protect_registrant_contact, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'PrivacyProtectRegistrantContact', traits: {"smithy.api#documentation" => "<p>Whether you want to conceal contact information from WHOIS queries. If you specify\n\t\t\t\t<code>true</code>, WHOIS (\"who is\") queries return contact information either for\n\t\t\tAmazon Registrar or for our registrar associate,\n\t\t\tGandi. If you specify <code>false</code>, WHOIS queries return the\n\t\t\tinformation that you entered for the registrant contact (the domain owner).</p>\n         <note>\n            <p>You must specify the same privacy setting for the administrative, billing, registrant, and\n\t\t\t\ttechnical contacts.</p>\n         </note>\n         <p>Default: <code>true</code>\n         </p>"}))
    RegisterDomainRequest.add_member(:privacy_protect_tech_contact, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'PrivacyProtectTechContact', traits: {"smithy.api#documentation" => "<p>Whether you want to conceal contact information from WHOIS queries. If you specify\n\t\t\t\t<code>true</code>, WHOIS (\"who is\") queries return contact information either for\n\t\t\tAmazon Registrar or for our registrar associate,\n\t\t\tGandi. If you specify <code>false</code>, WHOIS queries return the\n\t\t\tinformation that you entered for the technical contact.</p>\n         <note>\n            <p>You must specify the same privacy setting for the administrative, billing, registrant, and\n\t\t\t\ttechnical contacts.</p>\n         </note>\n         <p>Default: <code>true</code>\n         </p>"}))
